import type { FreshBaseline } from './applyBaseline'

/**
 * The fresh-install baseline is data, so it is a static file (`public/baseline/fresh-baseline.json`,
 * regenerated by `tests/int/fresh-baseline-parity.int.spec.ts` with `REGENERATE_BASELINE=1`) and not
 * code. The Worker reads it through the ASSETS binding only when a fresh install or a newly enabled
 * section needs it, so about half a megabyte of SQL text is not part of the Worker script.
 */
const PATH = '/baseline/fresh-baseline.json'

type AssetsBinding = { fetch(request: Request): Promise<Response> }

let cached: Promise<FreshBaseline> | undefined

async function read(): Promise<FreshBaseline> {
  // Worker: same context OpenNext's getCloudflareContext() reads.
  const ctx = (globalThis as Record<symbol, unknown>)[Symbol.for('__cloudflare-context__')] as { env?: { ASSETS?: AssetsBinding } } | undefined
  const assets = ctx?.env?.ASSETS
  if (assets) {
    const res = await assets.fetch(new Request(`https://assets.invalid${PATH}`))
    if (!res.ok) throw new Error(`Could not load ${PATH} (HTTP ${res.status}).`)
    return (await res.json()) as FreshBaseline
  }
  // Node (tests, local scripts): read the file from public/.
  const fs = await import(/* webpackIgnore: true */ 'node:fs/promises')
  const nodePath = await import(/* webpackIgnore: true */ 'node:path')
  return JSON.parse(await fs.readFile(nodePath.join(process.cwd(), 'public', PATH), 'utf8')) as FreshBaseline
}

export function loadFreshBaseline(): Promise<FreshBaseline> {
  if (!cached) {
    cached = read()
    cached.catch(() => {
      cached = undefined
    })
  }
  return cached
}
